export const PUBLISHED_RELEASES: PressRelease[] = PRESS_RELEASES.filter((r) => !r.draft);

export function getRelease(slug: string): PressRelease | undefined {
    return PRESS_RELEASES.find((r) => r.slug === slug);
}
